<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { computed, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';

interface SupplierProduct { id: string; product_name: string; variant_name: string | null; sku: string; supplier_sku: string | null; unit_cost: string; currency: string; minimum_order_quantity: number; order_multiple: number | null }
interface Supplier { id: string; name: string; code: string; supplier_products: SupplierProduct[] }
const props = defineProps<{ suppliers: Supplier[] }>();
const { t } = useI18n();
const form = useForm({ supplier_id: '', currency: '', expected_at: '', notes: '', items: [{ supplier_product_id: '', quantity: 1, unit_cost: '', description: '' }] });
const selectedSupplier = computed(() => props.suppliers.find((supplier) => supplier.id === form.supplier_id));
const products = computed(() => selectedSupplier.value?.supplier_products ?? []);
const addLine = () => form.items.push({ supplier_product_id: '', quantity: 1, unit_cost: '', description: '' });
const removeLine = (index: number) => { if (form.items.length > 1) form.items.splice(index, 1); };
const chooseProduct = (index: number) => { const line = form.items[index]; const product = products.value.find((item) => item.id === line.supplier_product_id); if (product) { line.unit_cost = product.unit_cost; line.quantity = product.minimum_order_quantity; form.currency = product.currency; } };
watch(() => form.supplier_id, () => { form.currency = ''; form.items = [{ supplier_product_id: '', quantity: 1, unit_cost: '', description: '' }]; });
const submit = () => { if (!form.processing) form.post('/admin/purchase-orders'); };
</script>

<template>
    <Head :title="t('procurement.orders.create')" />
    <AdminLayout><section class="mx-auto grid w-full max-w-5xl gap-5 sm:gap-6">
        <Breadcrumbs :items="[{ label: t('nav.procurement') }, { label: t('procurement.orders.title'), href: '/admin/purchase-orders' }, { label: t('common.create') }]" />
        <PageHeader :title="t('procurement.orders.create')" :eyebrow="t('common.allCompany')" :description="t('procurement.orders.createDescription')"><template #actions><Link href="/admin/purchase-orders" class="inline-flex min-h-9 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold">{{ t('procurement.backOrders') }}</Link></template></PageHeader>
        <aside class="rounded-md border border-admin-info-border bg-admin-info-bg px-4 py-3"><p class="text-sm font-semibold">{{ t('procurement.orders.draftTitle') }}</p><p class="mt-0.5 text-xs leading-5 text-admin-text-secondary">{{ t('procurement.orders.draftHelp') }}</p></aside>
        <form class="grid gap-5" @submit.prevent="submit"><section class="admin-card overflow-hidden"><header class="border-b border-admin-border px-5 py-4"><p class="admin-label text-admin-secondary">{{ t('procurement.orders.informationSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.orders.information') }}</h2></header><div class="grid gap-5 p-5 md:grid-cols-3"><label class="grid gap-1.5 text-sm font-semibold">{{ t('procurement.supplier') }} *<select v-model="form.supplier_id" required class="admin-control w-full px-3 text-sm font-normal"><option value="" disabled>{{ t('procurement.selectSupplier') }}</option><option v-for="supplier in suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }} · {{ supplier.code }}</option></select><FieldError :message="form.errors.supplier_id" /></label><label class="grid gap-1.5 text-sm font-semibold">{{ t('procurement.currency') }} *<input v-model="form.currency" required maxlength="3" pattern="[A-Za-z]{3}" class="admin-control w-full px-3 font-mono text-sm font-normal uppercase" /><FieldError :message="form.errors.currency" /></label><label class="grid gap-1.5 text-sm font-semibold">{{ t('procurement.expected') }}<input v-model="form.expected_at" type="date" class="admin-control w-full px-3 text-sm font-normal" /><FieldError :message="form.errors.expected_at" /></label><label class="grid gap-1.5 text-sm font-semibold md:col-span-3">{{ t('procurement.notes') }}<textarea v-model="form.notes" rows="3" maxlength="10000" class="admin-control w-full px-3 py-2 text-sm font-normal" /><FieldError :message="form.errors.notes" /></label></div></section>
            <section><div class="mb-3 flex flex-wrap items-end justify-between gap-3"><div><p class="admin-label text-admin-secondary">{{ t('procurement.orders.linesSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('procurement.orders.lines') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('procurement.orders.linesHelp') }}</p></div><button type="button" :disabled="!selectedSupplier" class="min-h-9 rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold disabled:opacity-40" @click="addLine">{{ t('procurement.addLine') }}</button></div><FieldError :message="form.errors.items" /><div class="grid gap-3"><article v-for="(line, index) in form.items" :key="index" class="admin-card grid gap-4 p-4 md:grid-cols-2 lg:grid-cols-[minmax(0,1fr)_7rem_10rem_auto]"><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.supplierProduct') }} *<select v-model="line.supplier_product_id" required :disabled="!selectedSupplier" class="admin-control w-full px-3 text-sm font-normal disabled:bg-admin-canvas" @change="chooseProduct(index)"><option value="" disabled>{{ selectedSupplier ? t('procurement.selectProduct') : t('procurement.selectSupplierFirst') }}</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.product_name }} · {{ product.sku }} · {{ t('procurement.moq', { count: product.minimum_order_quantity }) }}<template v-if="product.order_multiple"> · {{ t('procurement.multiple', { count: product.order_multiple }) }}</template></option></select><FieldError :message="form.errors[`items.${index}.supplier_product_id`]" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.quantity') }} *<input v-model.number="line.quantity" required type="number" min="1" class="admin-control w-full px-3 font-mono text-sm font-normal" /><FieldError :message="form.errors[`items.${index}.quantity`]" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.unitCost') }}<input v-model="line.unit_cost" inputmode="decimal" pattern="\d{1,15}(\.\d{1,4})?" class="admin-control w-full px-3 font-mono text-sm font-normal" /><FieldError :message="form.errors[`items.${index}.unit_cost`]" /></label><button type="button" :disabled="form.items.length === 1" class="min-h-9 self-end rounded-md px-3 text-sm font-semibold text-admin-danger disabled:opacity-30" :aria-label="t('procurement.removeLineNumber', { number: index + 1 })" @click="removeLine(index)">{{ t('common.remove') }}</button><label class="grid gap-1.5 text-xs font-semibold md:col-span-2 lg:col-span-4">{{ t('procurement.description') }}<textarea v-model="line.description" rows="2" maxlength="10000" class="admin-control w-full px-3 py-2 text-sm font-normal" /><FieldError :message="form.errors[`items.${index}.description`]" /></label></article></div></section>
            <footer class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Link href="/admin/purchase-orders" class="inline-flex min-h-10 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold">{{ t('common.cancel') }}</Link><button :disabled="form.processing || !products.length" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-50">{{ form.processing ? t('common.creating') : t('procurement.orders.createDraft') }}</button></footer>
        </form>
    </section></AdminLayout>
</template>
